import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/TEMPORARY.md","filePath":"manual-zh/TEMPORARY.md","lastUpdated":1785684581000}'),r={name:"manual-zh/TEMPORARY.md"};function c(p,t,s,n,i,h){return e(),a("div",null,[...t[0]||(t[0]=[o(`<h3 id="_13-6-temporary" tabindex="-1">13.6 TEMPORARY <a class="header-anchor" href="#_13-6-temporary" aria-label="Permalink to &quot;13.6 TEMPORARY&quot;">​</a></h3><pre><code>TEMPORARY.
</code></pre><p><code>TEMPORARY</code> 用于使其后的变换效果成为临时性的。这些变换仅影响下一个过程或类过程命令的执行。其效果不会被保存到活动数据集。</p><p><code>TEMPORARY</code> 唯一的说明就是命令名本身。</p><p><code>TEMPORARY</code> 不能出现在 <code>DO IF</code> 或 <code>LOOP</code> 结构内部。它在过程与类过程命令之间只能出现一次。</p><p><code>TEMPORARY</code> 之后不能使用临时变量。</p><h4 id="_13-6-1-temporary-示例" tabindex="-1">13.6.1 TEMPORARY 示例 <a class="header-anchor" href="#_13-6-1-temporary-示例" aria-label="Permalink to &quot;13.6.1 TEMPORARY 示例&quot;">​</a></h4><p>在示例 13.4 中有两个 <code>COMPUTE</code> 变换。其中一个紧接在 <code>TEMPORARY</code> 命令之后，因此只对下一个过程有效，在本例中即第一个 <code>DESCRIPTIVES</code> 命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable /x 1-2. begin data.  2  4 10 15 20 24 end data.  compute x=x/2.  temporary. compute x=x+3.  descriptives x. descriptives x.</span></span></code></pre></div><p><strong>示例 13.4：</strong> 在 <code>TEMPORARY</code> 之后运行 <code>COMPUTE</code> 变换</p><p>第一个 <code>DESCRIPTIVES</code> 过程读取的数据为 4、5、8、10.5、13、15。第二个 <code>DESCRIPTIVES</code> 过程读取的数据为 1、2、5、7.5、10、12。这是因为第二个 <code>COMPUTE</code> 变换对第二个 <code>DESCRIPTIVES</code> 过程不起作用。你可以在结果 13.2 中核对这些数值。</p><table tabindex="0"><thead><tr><th></th><th>N</th><th>均值</th><th>标准差</th><th>最小值</th><th>最大值</th></tr></thead><tbody><tr><td>x</td><td>6</td><td>9.25</td><td>4.38</td><td>4</td><td>15</td></tr><tr><td>有效 N（列表法）</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>缺失 N（列表法）</td><td>0</td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>N</td><td>均值</td><td>标准差</td><td>最小值</td><td>最大值</td></tr><tr><td>x</td><td>6</td><td>6.25</td><td>4.38</td><td>1</td><td>12</td></tr><tr><td>有效 N（列表法）</td><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>缺失 N（列表法）</td><td>0</td><td></td><td></td><td></td><td></td></tr></tbody></table><p><strong>结果 13.2：</strong> 在临时变换之后连续运行两个 <code>DESCRIPTIVES</code> 命令的结果</p>`,13)])])}const E=d(r,[["render",c]]);export{l as __pageData,E as default};
